content.text:
{
  "name": "WebDAV 临时目录集合",
  "name_en": "WebDAV Temporary Directory Collection",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于 WebDAV 服务器中表示仅保存在内存中的临时目录集合。这些临时目录在真正落盘前用于支持常见的“创建后再重命名/移动”目录创建流程，适合实验数据目录的暂存、属性查询和成员管理。",
  "description_en": "This is a non-physical software component that represents an in-memory temporary directory collection in a WebDAV server. These temporary directories are used to support the common create-then-rename/move workflow before a directory is materialized on disk, for tasks such as staging experimental data folders, querying properties, and managing members.",
  "actions": [
    {
      "action_name": "auto-getProperties",
      "description": "获取该 WebDAV 临时目录集合的属性。",
      "description_en": "Get the properties of this WebDAV temporary directory collection."
    },
    {
      "action_name": "auto-getMembers",
      "description": "获取该 WebDAV 临时目录集合中的成员项。",
      "description_en": "Get the members contained in this WebDAV temporary directory collection."
    },
    {
      "action_name": "auto-findMember",
      "description": "按名称查找该 WebDAV 临时目录集合中的成员项。",
      "description_en": "Find a member in this WebDAV temporary directory collection by name."
    },
    {
      "action_name": "auto-recvMember",
      "description": "接收并创建该 WebDAV 临时目录集合中的成员目录。",
      "description_en": "Receive and create a member directory in this WebDAV temporary directory collection."
    }
  ],
  "tag_hints": [
    "WebDAV",
    "temporary directory",
    "in-memory collection",
    "directory staging",
    "file server",
    "experimental data storage",
    "member lookup"
  ]
}

